function DocumentsModule({scope,onSelect}:{scope:"Ventes"|"Achats";onSelect:(type:string)=>void}){
 const paymentTab=scope==="Ventes"?"Règlements clients":"Règlements fournisseurs";
 const tabs=scope==="Ventes"?["Tous","Devis","Commandes","Bons de livraison","Factures","Retours","Avoirs",paymentTab]:["Tous","Commandes","Réceptions","Factures d’achat","Retours fournisseurs","Avoirs fournisseurs",paymentTab];
 const[tab,setTab]=useState(()=>typeof window!=="undefined"&&window.location.pathname.includes("/reglements")?paymentTab:"Tous");
 const[settlementOpen,setSettlementOpen]=useState(false);
 useEffect(()=>setTab(window.location.pathname.includes("/reglements")?paymentTab:"Tous"),[scope,paymentTab]);
 const docs=scope==="Ventes"?salesDocs:purchaseDocsWithAvoir;
 const matches=(d:DocRow,t:string)=>d.type===t||(t==="Retours fournisseurs"&&d.type==="Retours");
 const shown=tab==="Tous"?docs:docs.filter(d=>matches(d,tab));
 const metrics=moduleData[scope].metrics;
 const selectTab=(value:string)=>{setTab(value);if(value===paymentTab)window.history.pushState({},"",scope==="Ventes"?"/ventes/reglements":"/achats/reglements")};
 return <><div className="module-head"><div><h2>{scope}</h2><p>{scope==="Ventes"?"Cycle client, de l’offre au paiement.":"Cycle fournisseur, de la commande au règlement."}</p></div>{tab===paymentTab?<button className="primary" onClick={()=>setSettlementOpen(true)}><Plus size={17}/>{scope==="Ventes"?"Nouveau règlement client":"Nouveau règlement fournisseur"}</button>:<NewDocumentMenu scope={scope} onSelect={onSelect}/>}</div><div className="mini-grid">{metrics.map(([a,b])=><div className="panel mini" key={a}><span>{a}</span><strong>{b}</strong></div>)}</div><div className="panel table-panel"><div className="doc-tabs" role="tablist">{tabs.map(t=><button role="tab" aria-selected={tab===t} className={tab===t?"active":""} onClick={()=>selectTab(t)} key={t}>{t}<span>{t===paymentTab?(scope==="Ventes"?4:3):t==="Tous"?docs.length:docs.filter(d=>matches(d,t)).length}</span></button>)}</div>{tab===paymentTab?<SettlementTable scope={scope} onNew={()=>setSettlementOpen(true)}/>:<><div className="filters"><label><Search size={16}/><input placeholder="Rechercher un document ou un tiers…"/></label><select><option>Tous les statuts</option><option>Brouillon</option><option>Validé</option></select><select><option>Tous les dépôts</option><option>Dépôt principal</option><option>Mghogha</option></select><button onClick={()=>toast.success("Filtres appliqués")}>Filtrer</button></div><div className="table-wrap"><table><thead><tr><th>Document</th><th>{scope==="Ventes"?"Client":"Fournisseur"}</th><th>Type</th><th>Date</th><th>Montant</th><th>Statut</th><th>Actions</th></tr></thead><tbody>{shown.map(d=><tr key={d.number}><td><b>{d.number}</b></td><td>{d.party}</td><td>{d.type}</td><td>{d.date}</td><td>{d.amount}</td><td><span className={`status ${d.status==="Brouillon"?"draft":""}`}>{d.status}</span></td><td><RowActions doc={d}/></td></tr>)}</tbody></table></div><div className="table-foot"><span>{shown.length} document{shown.length>1?"s":""}</span><button>1</button></div></>}</div>{settlementOpen&&<SettlementForm scope={scope} onClose={()=>setSettlementOpen(false)}/>}</>
}
const clientSettlements=[
 ["RGC-2026-0418","Bâtiment Al Amal SARL","FA-2026-0842","Chèque","48 000 DH","14 sept.","20 sept.","Coffre du siège","En portefeuille"],
 ["RGC-2026-0417","Construction Nord","FA-2026-0838","Multichèque","72 000 DH","13 sept.","25 sept.","Service comptabilité","À déposer"],
 ["RGC-2026-0414","Établissements Rami","FA-2026-0821","Virement","36 420 DH","11 sept.","—","Banque","Encaissé"],
 ["RGC-2026-0409","Bâtiment Al Amal SARL","FA-2026-0804","Traite","124 500 DH","8 sept.","30 sept.","Caisse","Reçu"]
];
const supplierSettlements=[
 ["RGF-2026-0187","Ciments du Nord","FAC-2026-0228","Chèque","186 000 DH","14 sept.","22 sept.","Coffre du siège","En attente de signature"],
 ["RGF-2026-0184","Atlas Peintures","FAC-2026-0219","Multichèque","96 500 DH","12 sept.","28 sept.","Service comptabilité","Préparé"],
 ["RGF-2026-0180","Sanitaire Plus","FAC-2026-0211","Virement","82 640 DH","9 sept.","—","Banque","Débité"]
];
function SettlementTable({scope,onNew}:{scope:"Ventes"|"Achats";onNew:()=>void}){const rows=scope==="Ventes"?clientSettlements:supplierSettlements;return <><div className="filters payment-filters"><label><Search size={16}/><input placeholder={`Rechercher un ${scope==="Ventes"?"client":"fournisseur"}…`}/></label><select><option>Tous les modes</option><option>Espèces</option><option>Virement</option><option>Chèque</option><option>Multichèque</option><option>Traite</option></select><select><option>Tous les statuts</option><option>En portefeuille</option><option>{scope==="Ventes"?"Encaissé":"Débité"}</option></select><input type="date" aria-label="Date d’échéance"/><select><option>{scope==="Ventes"?"Tous les vendeurs":"Tous les fournisseurs"}</option><option>Yassine Bennani</option><option>Atlas Peintures</option></select></div><div className="payment-rule"><WalletCards/><span>Un règlement ne modifie jamais le stock. Les effets restent rattachés à leur facture et à leur tiers.</span></div><div className="table-wrap"><table className="settlement-table"><thead><tr>{["N° règlement",scope==="Ventes"?"Client":"Fournisseur","Facture","Mode","Montant","Date","Échéance","Emplacement actuel","Statut","Actions"].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={r[0]}><td><b>{r[0]}</b></td>{r.slice(1).map((v,i)=><td key={i}>{i===7?<span className={`status ${v==="Impayé"||v==="Rejeté"?"danger":""}`}>{v}</span>:v}</td>)}<td><button className="effect-detail" onClick={()=>toast.info(`Historique de déplacement — ${r[0]}`)}><Eye/>Voir</button></td></tr>)}</tbody></table></div><div className="table-foot"><span>{rows.length} règlements · données de démonstration</span><button onClick={onNew}>+</button></div></>}
type ChequeLine={number:string;bank:string;amount:number;due:string;location:string;status:string};
function SettlementForm({scope,onClose}:{scope:"Ventes"|"Achats";onClose:()=>void}){const isClient=scope==="Ventes";const total=124800,already=48000,remaining=total-already;const[amount,setAmount]=useState(0);const[mode,setMode]=useState("Espèces");const[error,setError]=useState("");const[cheques,setCheques]=useState<ChequeLine[]>([{number:"",bank:"Attijariwafa bank",amount:0,due:"2026-09-25",location:"Coffre du siège",status:isClient?"Reçu":"Préparé"}]);const chequeTotal=cheques.reduce((s,c)=>s+c.amount,0);const statuses=isClient?["Reçu","En portefeuille","À déposer","Déposé","En cours d’encaissement","Encaissé","Impayé","Annulé"]:["Préparé","En attente de signature","Signé","Conservé au siège","Remis au fournisseur","Déposé par le fournisseur","Débité","Annulé","Rejeté"];const update=(i:number,key:keyof ChequeLine,value:string|number)=>setCheques(cheques.map((c,n)=>n===i?{...c,[key]:value}:c));const validate=(draft=false)=>{if(amount<=0||amount>remaining){setError(`Le montant doit être compris entre 0 et ${money(remaining)}.`);return}if((mode==="Chèque"||mode==="Multichèque")&&(cheques.some(c=>!c.number||c.amount<=0)||(isClient?chequeTotal>amount:chequeTotal!==amount))){setError(isClient?"La somme des chèques ne peut pas dépasser le règlement.":"La somme des chèques doit correspondre exactement au règlement.");return}setError("");toast.success(`${isClient?"RGC-2026-0419":"RGF-2026-0188"} ${draft?"enregistré comme brouillon":"validé"}`);onClose()};return <div className="document-view"><div className="document-page"><div className="document-bar"><div className="document-title"><button onClick={onClose}><X/></button><span className="document-icon"><WalletCards/></span><div><p>{scope} / Règlements</p><h2>Nouveau règlement {isClient?"client":"fournisseur"} <em>{isClient?"RGC-2026-0419":"RGF-2026-0188"}</em></h2></div></div><div className="document-actions"><button className="secondary" onClick={onClose}>Annuler</button><button className="secondary" onClick={()=>validate(true)}>Enregistrer comme brouillon</button><button className="primary" onClick={()=>validate(false)}>Valider</button></div></div><div className="document-body">{error&&<div className="form-error"><AlertTriangle/>{error}</div>}<div className="rule-note"><WalletCards/><span>Le règlement diminue le solde dû, mais ne modifie jamais le stock. Un paiement partiel conserve la facture ouverte.</span></div><section className="form-section"><div className="section-heading"><span>1</span><div><h3>Facture et tiers</h3><p>Sélectionnez la facture à régler.</p></div></div><div className="form-grid document-fields"><label>{isClient?"Client":"Fournisseur"} *<select><option>{isClient?"Construction Nord":"Ciments du Nord"}</option><option>{isClient?"Bâtiment Al Amal SARL":"Atlas Peintures"}</option></select></label><label>Facture associée *<select><option>{isClient?"FA-2026-0871":"FAC-2026-0228"}</option></select></label><label>{isClient?"Numéro de facture":"N° facture fournisseur"}<input value={isClient?"FA-2026-0871":"FN-45821"} readOnly/></label><label>Montant total<input value={money(total)} readOnly/></label><label>Montant déjà {isClient?"payé":"réglé"}<input value={money(already)} readOnly/></label><label>Reste à payer<input value={money(remaining)} readOnly/></label></div></section><section className="form-section"><div className="section-heading"><span>2</span><div><h3>Nouveau règlement</h3><p>Le reste à payer est recalculé automatiquement.</p></div></div><div className="form-grid document-fields"><label>Montant du nouveau règlement *<input aria-label="Montant du nouveau règlement" type="number" min="0" max={remaining} value={amount} onChange={e=>setAmount(+e.target.value)}/></label><label>Mode de {isClient?"paiement":"règlement"} *<select value={mode} onChange={e=>setMode(e.target.value)}><option>Espèces</option><option>Virement</option><option>Chèque</option><option>Multichèque</option><option>Traite</option></select></label><label>Date du règlement *<input type="date" defaultValue="2026-09-14"/></label><label>Reste après règlement<input className="remaining-input" value={money(Math.max(0,remaining-amount))} readOnly/></label><label className="observations-wide">Observations<textarea placeholder="Ajouter une observation…"/></label></div></section>{(mode==="Chèque"||mode==="Multichèque")&&<section className="form-section"><div className="section-heading"><span>3</span><div><h3>{mode==="Multichèque"?"Détail des chèques":"Détail du chèque"}</h3><p>Suivez chaque effet jusqu’à son encaissement ou son débit.</p></div></div>{cheques.map((c,i)=><div className="cheque-card" key={i}><div className="cheque-index">{i+1}</div><div className="cheque-fields"><label>N° chèque *<input value={c.number} onChange={e=>update(i,"number",e.target.value)}/></label><label>Banque *<select value={c.bank} onChange={e=>update(i,"bank",e.target.value)}><option>Attijariwafa bank</option><option>Banque Populaire</option><option>BMCI</option><option>CIH Bank</option></select></label><label>{isClient?"Titulaire":"Bénéficiaire"}<input defaultValue={isClient?"Construction Nord":"Ciments du Nord"}/></label><label>Montant *<input aria-label={`Montant chèque ${i+1}`} type="number" value={c.amount} onChange={e=>update(i,"amount",+e.target.value)}/></label><label>Date d’échéance<input type="date" value={c.due} onChange={e=>update(i,"due",e.target.value)}/></label><label>Emplacement<input value={c.location} onChange={e=>update(i,"location",e.target.value)}/></label><label>Statut<select value={c.status} onChange={e=>update(i,"status",e.target.value)}>{statuses.map(s=><option key={s}>{s}</option>)}</select></label><label>Observation<input placeholder="Commentaire…"/></label></div>{cheques.length>1&&<button onClick={()=>setCheques(cheques.filter((_,n)=>n!==i))}><X/></button>}</div>)}{mode==="Multichèque"&&<button className="add-line" onClick={()=>setCheques([...cheques,{number:"",bank:"Banque Populaire",amount:0,due:"2026-10-05",location:"Service comptabilité",status:isClient?"Reçu":"Préparé"}])}><Plus/>Ajouter un chèque</button>}<div className={`cheque-total ${isClient?chequeTotal<=amount:chequeTotal===amount?"ok":"warning"}`}><span>Total des chèques</span><b>{money(chequeTotal)}</b><em>Montant du règlement : {money(amount)}</em></div></section>}<section className="form-section effect-history"><div className="section-heading"><span>4</span><div><h3>Historique de l’emplacement</h3><p>Traçabilité fictive du déplacement de l’effet.</p></div></div>{[["14 sept. 14:18","Caisse","Coffre du siège","Amine Mansouri","Effet vérifié"],["14 sept. 10:42","Client","Caisse","Sara Alaoui","Reçu avec le règlement"]].map(x=><div className="history-row" key={x[0]}><i/><b>{x[0]}</b><span>{x[1]} → {x[2]}</span><span>{x[3]}</span><em>{x[4]}</em></div>)}</section></div><div className="mobile-document-actions"><button className="secondary" onClick={onClose}>Annuler</button><button className="secondary" onClick={()=>validate(true)}>Brouillon</button><button className="primary" onClick={()=>validate(false)}>Valider</button></div></div></div>}
function RowActions({doc}:{doc:DocRow}){const[open,setOpen]=useState(false);const act=(m:string)=>{toast.success(`${m} — ${doc.number}`);setOpen(false)};return <div className="row-actions"><button aria-label={`Actions pour ${doc.number}`} onClick={e=>{e.stopPropagation();setOpen(!open)}}><Ellipsis size={17}/></button>{open&&<div className="row-menu"><button onClick={()=>act("Ouverture du document")}><Eye/>Voir</button>{doc.status==="Brouillon"&&<button onClick={()=>act("Modification ouverte")}><Pencil/>Modifier</button>}<button onClick={()=>act("Impression simulée")}><Printer/>Imprimer</button><button onClick={()=>act("PDF téléchargé en simulation")}><Download/>Télécharger en PDF</button><button onClick={()=>act("Document dupliqué")}><Copy/>Dupliquer</button>{doc.next&&<button className="convert" onClick={()=>act(`Conversion vers ${doc.next}`)}><ArrowRight/>Convertir en {doc.next}</button>}<button className="cancel" onClick={()=>act("Annulation simulée")}><Ban/>Annuler</button></div>}</div>}
function Module({title,openDocument}:{title:string,openDocument:(type:string)=>void}){const[partyDetail,setPartyDetail]=useState<string|null>(null);if(title==="Ventes"||title==="Achats")return <DocumentsModule scope={title} onSelect={openDocument}/>;if(title==="Rapports")return <Reports/>;if(title==="Paramètres")return <SettingsPage/>;const d=moduleData[title]||moduleData.Produits;const isParty=title==="Clients"||title==="Fournisseurs";return <><div className="module-head"><div><h2>{title}</h2><p>Consultez, filtrez et gérez les opérations de ce module.</p></div><button className="primary" onClick={()=>toast.success(`${d.action} — formulaire ouvert en mode démonstration`)}><Plus size={17}/>{d.action}</button></div><div className="mini-grid">{d.metrics.map(([a,b])=><div className="panel mini" key={a}><span>{a}</span><strong>{b}</strong></div>)}</div><div className="panel table-panel"><div className="filters"><label><Search size={16}/><input placeholder={`Rechercher dans ${title.toLowerCase()}…`}/></label><select><option>Tous les statuts</option><option>Actif</option><option>En attente</option></select><select><option>Tous les dépôts</option><option>Dépôt principal</option><option>Mghogha</option></select><button onClick={()=>toast.success("Filtres appliqués")}>Filtrer</button></div><div className="table-wrap"><table><thead><tr>{d.heads.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{d.rows.map((r,i)=><tr key={i} onClick={()=>isParty?setPartyDetail(r[0]):toast.info(`Fiche « ${r[0]} » ouverte`)}>{r.map((v,j)=><td key={j}>{j===r.length-1?<span className={`status ${v.includes("Impayé")||v.includes("Faible")?"danger":""}`}>{v}</span>:v}</td>)}</tr>)}</tbody></table></div><div className="table-foot"><span>{d.rows.length} résultats de démonstration</span><button>1</button></div></div>{partyDetail&&<PartyEffectsDetail kind={title as "Clients"|"Fournisseurs"} name={partyDetail} onClose={()=>setPartyDetail(null)}/>}</>}
function PartyEffectsDetail({kind,name,onClose}:{kind:"Clients"|"Fournisseurs";name:string;onClose:()=>void}){const client=kind==="Clients";const rows=client?clientSettlements.filter(r=>r[1].includes(name.split(" ")[0])):supplierSettlements.filter(r=>r[1].includes(name.split(" ")[0]));const shown=rows.length?rows:(client?clientSettlements.slice(0,2):supplierSettlements.slice(0,2));return <div className="modal-overlay" onMouseDown={onClose}><div className="party-sheet" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={onClose}><X/></button><p className="eyebrow">Fiche {client?"client":"fournisseur"}</p><h2>{name}</h2><div className="party-kpis"><div><span>Montant {client?"encaissé":"réglé"}</span><b>{client?"486 200 DH":"412 800 DH"}</b></div><div><span>Reste à payer</span><b>{client?"72 000 DH":"186 000 DH"}</b></div><div><span>{client?"Impayés":"Prochaine échéance"}</span><b>{client?"0 DH":"22 sept. 2026"}</b></div></div><h3>{client?"Règlements et effets reçus":"Règlements et effets remis"}</h3><div className="table-wrap"><table><thead><tr><th>Règlement</th><th>Facture</th><th>Mode</th><th>Montant</th><th>Échéance</th><th>Emplacement</th><th>Statut</th></tr></thead><tbody>{shown.map(r=><tr key={r[0]}>{[r[0],r[2],r[3],r[4],r[6],r[7],r[8]].map((v,i)=><td key={i}>{i===6?<span className="status">{v}</span>:v}</td>)}</tr>)}</tbody></table></div><div className="effect-history"><h3>Derniers déplacements</h3><div className="history-row"><i/><b>14 sept. 14:18</b><span>Caisse → Coffre du siège</span><span>Amine Mansouri</span><em>Effet vérifié</em></div><div className="history-row"><i/><b>13 sept. 10:42</b><span>Service commercial → Caisse</span><span>Sara Alaoui</span><em>Réception confirmée</em></div></div></div></div>}
function Reports(){return <><div className="module-head"><div><h2>Rapports</h2><p>Analyse consolidée de l’activité commerciale.</p></div><div className="report-actions"><button onClick={()=>toast.success("Export Excel simulé")}>Exporter Excel</button><button className="primary" onClick={()=>toast.success("Export PDF simulé")}>Exporter PDF</button></div></div><div className="report-grid">{["Ventes par période","Ventes par client","Ventes par vendeur","Ventes par produit","Ventes par dépôt","Achats par fournisseur","État du stock","Valorisation du stock","Créances clients","Dettes fournisseurs","Échéancier des effets","Produits à faible rotation"].map((r,i)=><button className="panel report-card" key={r} onClick={()=>toast.info(`${r} — aperçu chargé`)}><FileBarChart/><div><strong>{r}</strong><span>{i%3===0?"Mis à jour aujourd’hui":"Données consolidées"}</span></div><ChevronDown/></button>)}</div></>}
function SettingsPage(){return <><div className="module-head"><div><h2>Paramètres et permissions</h2><p>Simulation des rôles et journal d’activité.</p></div></div><div className="settings-grid"><div className="panel"><h3>Rôles utilisateurs</h3>{["Administrateur","Direction","Commercial","Magasinier","Responsable des achats","Caissier / comptable"].map((x,i)=><div className="role" key={x}><span>{x}</span><b>{i===0?"Tous les droits":i===1?"Lecture et validation":"Accès limité"}</b><button onClick={()=>toast.info(`Permissions de ${x}`)}>Voir les permissions</button></div>)}</div><div className="panel"><h3>Journal d’activité</h3>{[["Amine Mansouri","Validation facture FA-2026-0842","14 sept. 14:32"],["Sara Alaoui","Modification client Construction Nord","14 sept. 13:48"],["Omar El Idrissi","Création devis DEV-2026-1194","14 sept. 11:26"],["Hamza Magasin","Transfert TR-0198 validé","14 sept. 10:04"]].map(x=><div className="activity" key={x[1]}><div className="avatar">{x[0][0]}</div><div><strong>{x[1]}</strong><span>{x[0]} · {x[2]}</span></div></div>)}</div></div></>}
function QuoteDialog({open,setOpen}:{open:boolean,setOpen:(v:boolean)=>void}){const[lines,setLines]=useState([{product:"Ciment CPJ 45 — sac 50 kg",qty:120,price:89,discount:2},{product:"Peinture façade blanche — 25 kg",qty:8,price:465,discount:0}]);const ht=lines.reduce((s,l)=>s+l.qty*l.price*(1-l.discount/100),0),vat=ht*.2;if(!open)return null;return <div className="modal-overlay" role="dialog" aria-modal="true" onMouseDown={()=>setOpen(false)}><div className="quote-dialog" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setOpen(false)}><X/></button><div className="dialog-head"><h2>Nouveau devis <span>DEV-2026-1195</span></h2><p>Le devis ne modifie pas le stock disponible.</p></div><div className="form-grid"><label>Client<select><option>Bâtiment Al Amal SARL</option><option>Construction Nord</option></select></label><label>Vendeur<select><option>Yassine Bennani</option><option>Sara Alaoui</option></select></label><label>Dépôt<select><option>Dépôt principal</option><option>Route de Rabat</option></select></label><label>Validité<input type="date" defaultValue="2026-09-30"/></label></div><div className="quote-lines"><div className="line-head"><span>Article</span><span>Qté</span><span>Prix HT</span><span>Remise</span><span>Total HT</span><span/></div>{lines.map((l,i)=><div className="quote-line" key={i}><select value={l.product} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,product:e.target.value}:x))}><option>Ciment CPJ 45 — sac 50 kg</option><option>Peinture façade blanche — 25 kg</option><option>Tube PVC évacuation Ø110</option></select><input type="number" value={l.qty} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,qty:+e.target.value}:x))}/><input type="number" value={l.price} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,price:+e.target.value}:x))}/><input type="number" value={l.discount} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,discount:+e.target.value}:x))}/><b>{(l.qty*l.price*(1-l.discount/100)).toLocaleString("fr-FR")} DH</b><button onClick={()=>setLines(lines.filter((_,n)=>n!==i))}><X size={16}/></button></div>)}</div><button className="add-line" onClick={()=>setLines([...lines,{product:"Tube PVC évacuation Ø110",qty:1,price:118,discount:0}])}><Plus size={15}/> Ajouter une ligne</button><div className="quote-bottom"><label>Conditions de paiement<textarea defaultValue="50% à la commande, solde à 30 jours."/></label><div><p><span>Total HT</span><b>{ht.toLocaleString("fr-FR")} DH</b></p><p><span>TVA 20%</span><b>{vat.toLocaleString("fr-FR")} DH</b></p><p className="grand"><span>Total TTC</span><b>{(ht+vat).toLocaleString("fr-FR")} DH</b></p></div></div><div className="dialog-foot"><button className="secondary" onClick={()=>toast.success("Brouillon enregistré")}>Enregistrer comme brouillon</button><button className="primary" onClick={()=>{toast.success("Devis validé et prêt à convertir");setOpen(false)}}>Valider le devis</button></div></div></div>}
function DocumentForm({type,onClose}:{type:string;onClose:()=>void}){const c=docConfigs[type];const isInvoice=type==="Nouvelle facture"||type==="Nouvelle facture d’achat";const isPurchase=c.scope==="Achats";const[party,setParty]=useState(c.partyOptions[0]);const[supplierNo,setSupplierNo]=useState("");const[linked,setLinked]=useState("Aucun document lié");const[paid,setPaid]=useState(0);const[error,setError]=useState("");const[lines,setLines]=useState([{product:"Ciment CPJ 45 — sac 50 kg",qty:40,price:isPurchase?72:89,discount:0,vat:20},{product:"Tube PVC évacuation Ø110",qty:12,price:isPurchase?82:118,discount:2,vat:20}]);const ht=lines.reduce((s,l)=>s+l.qty*l.price*(1-l.discount/100),0);const vat=lines.reduce((s,l)=>s+l.qty*l.price*(1-l.discount/100)*l.vat/100,0);const total=ht+vat;const validate=(draft=false)=>{if(!party||lines.length===0||lines.some(l=>l.qty<=0||l.price<=0)||(type==="Nouvelle facture d’achat"&&!supplierNo)){setError(type==="Nouvelle facture d’achat"&&!supplierNo?"Le numéro de facture fournisseur est obligatoire.":"Complétez les champs obligatoires et ajoutez au moins un article valide.");return}setError("");toast.success(draft?`${c.number} enregistré comme brouillon`:`${c.number} validé avec succès`);onClose()};const Icon=c.icon;return <div className="document-view"><div className="document-page"><div className="document-bar"><div className="document-title"><button onClick={onClose}><X/></button><span className="document-icon"><Icon/></span><div><p>{c.scope} / Nouveau document</p><h2>{c.title} <em>{c.number}</em></h2></div></div><div className="document-actions"><button className="secondary" onClick={onClose}>Annuler</button><button className="secondary" onClick={()=>validate(true)}>Enregistrer comme brouillon</button><button className="primary" onClick={()=>validate(false)}><CheckCircle2/>Valider</button></div></div><div className="document-body">{error&&<div className="form-error"><AlertTriangle/>{error}</div>}<div className="rule-note"><AlertTriangle/><span>{c.note}</span></div><section className="form-section"><div className="section-heading"><span>1</span><div><h3>Informations générales</h3><p>Les champs marqués d’un astérisque sont obligatoires.</p></div></div><div className="form-grid document-fields"><label>{c.party} *<select value={party} onChange={e=>setParty(e.target.value)}>{c.partyOptions.map(x=><option key={x}>{x}</option>)}</select></label>{!isPurchase&&<label>Vendeur *<select><option>Yassine Bennani</option><option>Sara Alaoui</option></select></label>}{type==="Nouvelle facture d’achat"&&<label>N° facture fournisseur *<input value={supplierNo} onChange={e=>setSupplierNo(e.target.value)} placeholder="Ex. FN-45821"/></label>}<label>Dépôt *<select><option>Dépôt principal</option><option>Route de Rabat</option><option>Mghogha</option></select></label><label>Date du document *<input type="date" defaultValue="2026-09-14"/></label><label>{c.dateLabel} *<input type="date" defaultValue="2026-09-30"/></label>{isInvoice&&<label>Document d’origine<select value={linked} onChange={e=>setLinked(e.target.value)}><option>Aucun document lié</option><option>{isPurchase?"REC-2026-0264 — validée":"BL-2026-0641 — validé"}</option></select></label>}</div>{isInvoice&&<div className={`stock-choice ${linked!=="Aucun document lié"?"disabled":""}`}><input id="stock-now" type="checkbox" disabled={linked!=="Aucun document lié"}/><label htmlFor="stock-now"><strong>{c.stockOption}</strong><span>{linked!=="Aucun document lié"?`Stock déjà mouvementé par ${isPurchase?"la réception":"le bon de livraison"} sélectionné.`:"Activez cette option pour mouvementer le stock lors de la validation."}</span></label></div>}</section><section className="form-section"><div className="section-heading"><span>2</span><div><h3>Articles</h3><p>Ajoutez les produits et ajustez quantités, prix, remises et TVA.</p></div></div><div className="document-lines"><div className="document-line-head"><span>Article</span><span>Quantité</span><span>Prix {isPurchase?"d’achat":"unitaire"}</span><span>Remise %</span><span>TVA %</span><span>Total HT</span><span/></div>{lines.map((l,i)=><div className="document-line" key={i}><select value={l.product} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,product:e.target.value}:x))}><option>Ciment CPJ 45 — sac 50 kg</option><option>Peinture façade blanche — 25 kg</option><option>Tube PVC évacuation Ø110</option><option>Carrelage sol grès 60×60</option></select><input aria-label={`Quantité ligne ${i+1}`} type="number" min="1" value={l.qty} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,qty:+e.target.value}:x))}/><input aria-label={`Prix ligne ${i+1}`} type="number" min="0" value={l.price} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,price:+e.target.value}:x))}/><input aria-label={`Remise ligne ${i+1}`} type="number" min="0" max="100" value={l.discount} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,discount:+e.target.value}:x))}/><select value={l.vat} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,vat:+e.target.value}:x))}><option value="20">20%</option><option value="14">14%</option><option value="10">10%</option><option value="0">0%</option></select><b>{money(l.qty*l.price*(1-l.discount/100))}</b><button aria-label={`Supprimer la ligne ${i+1}`} onClick={()=>setLines(lines.filter((_,n)=>n!==i))}><X/></button></div>)}</div><button className="add-line" onClick={()=>setLines([...lines,{product:"Peinture façade blanche — 25 kg",qty:1,price:isPurchase?330:465,discount:0,vat:20}])}><Plus/>Ajouter un article</button></section><section className="form-section payment-section"><div><div className="section-heading"><span>3</span><div><h3>{isPurchase?"Règlement et observations":"Paiement et observations"}</h3><p>Précisez les conditions financières du document.</p></div></div><div className="payment-fields"><label>{c.paymentLabel} *<select>{c.paymentModes.map(x=><option key={x}>{x}</option>)}</select></label>{isInvoice&&<label>Montant {isPurchase?"réglé":"payé"}<input type="number" min="0" max={total} value={paid} onChange={e=>setPaid(+e.target.value)}/></label>}<label className="observations">Observations<textarea placeholder="Ajouter une note interne ou une instruction…"/></label></div></div><div className="totals-card"><p><span>Total HT</span><b>{money(ht)}</b></p><p><span>Total TVA</span><b>{money(vat)}</b></p><p className="total-ttc"><span>Total TTC</span><b>{money(total)}</b></p>{isInvoice&&<><p><span>Montant {isPurchase?"réglé":"payé"}</span><b>{money(paid)}</b></p><p className="remaining"><span>Reste à payer</span><b>{money(Math.max(0,total-paid))}</b></p></>}</div></section></div><div className="mobile-document-actions"><button className="secondary" onClick={onClose}>Annuler</button><button className="secondary" onClick={()=>validate(true)}>Brouillon</button><button className="primary" onClick={()=>validate(false)}>Valider</button></div></div></div>}
function money(value:number){return `${value.toLocaleString("fr-FR",{minimumFractionDigits:2,maximumFractionDigits:2})} DH`}
function ToastHost(){const[msg,setMsg]=useState("");useEffect(()=>{const fn=(e:Event)=>{setMsg((e as CustomEvent).detail);window.setTimeout(()=>setMsg(""),2800)};window.addEventListener("demo-toast",fn);return()=>window.removeEventListener("demo-toast",fn)},[]);return msg?<div className="demo-toast"><span>✓</span>{msg}</div>:null}
